{
  "aggregate_id": "DEF-NRS-484A-285::traffic",
  "classifications": [
    {
      "class": "ru.bicycle",
      "verdict": "supported",
      "reason": "Human-powered ridden devices fall within 'other conveyances,' notwithstanding their exclusion from the nested definition of 'vehicle.'"
    },
    {
      "class": "ru.bus",
      "verdict": "supported",
      "reason": "Passenger-carrying motor vehicles satisfy the admitting definition of 'vehicle,' and no exception removes this class."
    },
    {
      "class": "ru.child",
      "verdict": "supported",
      "reason": "The contract describes pedestrians, whom the controlling definition expressly admits without an age exception."
    },
    {
      "class": "ru.commercial_motor_vehicle",
      "verdict": "supported",
      "reason": "The contract describes vehicles within 'vehicles and other conveyances,' with no exception based on commercial mass or licensing."
    },
    {
      "class": "ru.electric_bicycle",
      "verdict": "supported",
      "reason": "Ridden bicycles with assisting electric motors fall within 'other conveyances' despite the electric-bicycle exception to 'vehicle.'"
    },
    {
      "class": "ru.electric_scooter",
      "verdict": "supported",
      "reason": "Standing or seated electric scooters are admitted by 'other conveyances' despite their exclusion from the nested definition of 'vehicle.'"
    },
    {
      "class": "ru.emergency_vehicle",
      "verdict": "supported",
      "reason": "The admitting words reach the contract's vehicles without requiring emergency-response conduct."
    },
    {
      "class": "ru.fire_apparatus",
      "verdict": "supported",
      "reason": "The contract's fire-fighting vehicles fall within the admitting vehicle language, with no applicable exception."
    },
    {
      "class": "ru.moped",
      "verdict": "supported",
      "reason": "The quoted motor-driven scooter, cycle or similar vehicle language admits the contract's jurisdiction-classed mopeds, which no vehicle exception removes."
    },
    {
      "class": "ru.motor_vehicle",
      "verdict": "supported",
      "reason": "The contract's self-propelled nonrail vehicles fall within the admitting vehicle language, with no applicable exception."
    },
    {
      "class": "ru.motorcycle",
      "verdict": "supported",
      "reason": "Motor vehicles ridden astride on two or three wheels satisfy the admitting vehicle language, with no applicable exception."
    },
    {
      "class": "ru.official_vehicle",
      "verdict": "supported",
      "reason": "The contract's road-service vehicles fall within 'vehicles and other conveyances,' without any requirement that they be emergency vehicles."
    },
    {
      "class": "ru.pedestrian",
      "verdict": "supported",
      "reason": "The express admission of pedestrians and the nested pedestrian definition match the contract's persons on foot, in wheelchairs or on devices treated as on foot."
    },
    {
      "class": "ru.pedestrian_with_white_cane_or_guide_animal",
      "verdict": "supported",
      "reason": "The contract describes pedestrians, and the express pedestrian admission contains no exception for their cane, guide animal or accompanying person."
    },
    {
      "class": "ru.rail_vehicle",
      "verdict": "contradicted",
      "reason": "The stationary-rail exception limits 'vehicle,' while 'other conveyances' admits rail conveyances, and highway use for travel is a scene condition rather than a class exclusion."
    },
    {
      "class": "ru.school_bus",
      "verdict": "supported",
      "reason": "Buses designated for carrying school children satisfy the admitting vehicle language, with no exception based on designation or markings."
    },
    {
      "class": "ru.taxicab",
      "verdict": "supported",
      "reason": "Passenger vehicles for hire satisfy the admitting vehicle language, with no exception based on hire or markings."
    },
    {
      "class": "ru.tour_bus_or_limousine",
      "verdict": "supported",
      "reason": "Both the contract's buses and its lengthened passenger vehicles for hire satisfy the admitting vehicle language."
    },
    {
      "class": "ru.trailer_or_combination",
      "verdict": "supported",
      "reason": "The words 'transported or drawn' admit drawn vehicles, and 'either singly or together' admits combinations."
    },
    {
      "class": "ru.transit_bus",
      "verdict": "supported",
      "reason": "Buses in public transit service satisfy the admitting vehicle language, with no exception based on service or identification."
    },
    {
      "class": "ru.truck",
      "verdict": "supported",
      "reason": "Motor vehicles built to carry goods satisfy the express admission of devices by which property may be transported."
    }
  ]
}

